INSERT INTO "recipes" ("external_id", "title", "description", "category", "cuisine", "prep_time_minutes", "cook_time_minutes", "servings", "difficulty", "tags", "image_path", "ingredients", "instructions")
VALUES
('hortobagyi-husos-palacsinta', 'Hortobágyi húsos palacsinta', 'Klasszikus magyar előétel szaftos pörkölttel töltött palacsintából, tejfölös-paprikás mártással.', 'Főétel', 'Magyar', 30, 45, 4, 'közepes', '["húsos","palacsinta","pörkölt","hagyományos"]'::jsonb, 'Images/hortobagyi-palacsinta-hus.webp', '[{"group":"Palacsintatészta","items":[{"name":"finomliszt","amount":200,"unit":"g"},{"name":"tojás","amount":2,"unit":"db"},{"name":"tej","amount":300,"unit":"ml"},{"name":"szénsavas ásványvíz","amount":100,"unit":"ml"},{"name":"só","amount":1,"unit":"csipet"},{"name":"étolaj (a sütéshez)","amount":2,"unit":"evőkanál"}]},{"group":"Töltelék és mártás","items":[{"name":"darált sertés- vagy borjúhús","amount":500,"unit":"g"},{"name":"vöröshagyma","amount":1,"unit":"db"},{"name":"étolaj / zsír","amount":2,"unit":"evőkanál"},{"name":"fűszerpaprika","amount":1.5,"unit":"evőkanál"},{"name":"TV paprika","amount":1,"unit":"db"},{"name":"paradicsom","amount":1,"unit":"db"},{"name":"tejföl","amount":200,"unit":"g"},{"name":"finomliszt (a habaráshoz)","amount":1,"unit":"evőkanál"},{"name":"só, bors","amount":null,"unit":"ízlés szerint"}]}]'::jsonb, '[{"section":"Pörköltalap és hús","steps":["A finomra vágott vöröshagymát az olajon vagy zsíron üvegesre pirítjuk.","Lehúzzuk a tűzről, rászórjuk a fűszerpaprikát, majd hozzáadjuk a darált húst, a kockázott paprikát és paradicsomot.","Sózzuk, borsozzuk, és kevés vízzel felöntve puhára főzzük a pörköltet."]},{"section":"Palacsinta","steps":["A lisztből, tojásból, tejből, ásványvízből és sóból csomómentes tésztát keverünk.","A szokásosnál kissé vastagabb palacsintákat sütünk ki."]},{"section":"Összeállítás","steps":["A megsült húst leszűrjük, a szaftját félretesszük. A húst finomra daráljuk vagy felaprítjuk, és kevés szafttal összekeverjük.","Megtöltjük a palacsintákat, a széleiket behajtva feltekerjük vagy batyuvá formázzuk őket.","A maradék szafthoz hozzáadjuk a tejföllel elkevert lisztet, összeforraljuk, majd a palacsintákra öntve tálaljuk."]}]'::jsonb),
('citromos-turos-pite-liszt-nelkul', 'Citromos-túrós pite liszt nélkül', 'Könnyű, krémes és frissítő sütemény liszt hozzáadása nélkül, intenzív citromos ízzel.', 'Desszert', 'Magyar', 10, 40, 8, 'könnyű', '["túró","citrom","pite","gluténmentes","lisztmentes","sütemény"]'::jsonb, 'Images/citromos-turos-pite-liszt-nelkul.webp', '[{"group":"Alaphozzávalók","items":[{"name":"sovány túró","amount":250,"unit":"g"},{"name":"tojás (M-es)","amount":5,"unit":"db"},{"name":"tejföl","amount":150,"unit":"g"},{"name":"vaníliás pudingpor","amount":2,"unit":"csomag"},{"name":"rizsdara","amount":4,"unit":"evőkanál"},{"name":"teavaj (olvasztott)","amount":2,"unit":"evőkanál"},{"name":"négyszeres erejű édesítőszer","amount":1,"unit":"evőkanál"},{"name":"mazsola","amount":1,"unit":"marék"},{"name":"kezeletlen citrom","amount":2,"unit":"db"},{"name":"vaníliaaroma","amount":1,"unit":"kávéskanál"},{"name":"sütőpor","amount":0.5,"unit":"csomag"},{"name":"fahéj","amount":1,"unit":"teáskanál"},{"name":"só","amount":1,"unit":"csipet"}]}]'::jsonb, '[{"section":"Előkészítés és krém","steps":["A tojásokat szétválasztjuk, a fehérjéket egy csipet sóval kemény habbá verjük.","A tojássárgájákat elektromos habverővel kb. 5 perc alatt habosra keverjük az édesítőszerrel.","Hozzáadjuk a citromok reszelt héját és az egyik átszűrt levét, az olvasztott vajat, a tejfölt, a fahéjat, a vaníliaaromát és a túrót (érdemes botmixerrel krémesíteni).","Egy kis tálban összekeverjük a rizsdarát, a pudingport, a sütőport és az előzőleg beáztatott mazsolát, majd ezt fakanállal a túrós alapba forgatjuk.","Végül óvatosan hozzáadjuk a keményre vert tojáshabot is."]},{"section":"Sütés","steps":["A masszát egy sütőpapírral kibélelt tepsibe öntjük.","180 °C-ra előmelegített sütőben 35-40 perc alatt pirosra sütjük, majd teljesen hagyjuk kihűlni tálalás előtt."]}]'::jsonb),
('gulyasleves', 'Klasszikus gulyásleves', 'Bőséges, gazdag hagyományos magyar leves marhahúsból, csipetkével és zöldségekkel.', 'Leves', 'Magyar', 30, 120, 6, 'közepes', '["marha","leves","hagyományos","pörköltalap"]'::jsonb, 'Images/klasszikus-gulyasleves-2-scaled-gn_-N2.jpg', '[{"group":"Pörköltalap és hús","items":[{"name":"marhalábszár","amount":600,"unit":"g"},{"name":"vöröshagyma","amount":2,"unit":"db"},{"name":"sertészsír","amount":2,"unit":"evőkanál"},{"name":"fűszerpaprika","amount":2,"unit":"evőkanál"},{"name":"fokhagyma","amount":2,"unit":"gerezd"},{"name":"köménymag","amount":1,"unit":"teáskanál"},{"name":"só, bors","amount":null,"unit":"ízlés szerint"}]},{"group":"Zöldségek","items":[{"name":"sárgarépa","amount":2,"unit":"db"},{"name":"petrezselyemgyökér","amount":1,"unit":"db"},{"name":"burgonya","amount":400,"unit":"g"},{"name":"TV paprika","amount":1,"unit":"db"},{"name":"paradicsom","amount":1,"unit":"db"}]},{"group":"Csipetke","items":[{"name":"finomliszt","amount":80,"unit":"g"},{"name":"tojás","amount":1,"unit":"db"},{"name":"só","amount":1,"unit":"csipet"}]}]'::jsonb, '[{"section":"Pörköltalap","steps":["A finomra vágott hagymát a zsíron üvegesre pirítjuk.","Lehúzzuk a tűzről, rászórjuk a fűszerpaprikát, átkeverjük, majd hozzáadjuk a kockázott marhahúst és a zúzott fokhagymát.","Mellédobjuk a kockázott paprikát és paradicsomot, sózzuk, köménnyel fűszerezzük, majd kevés vízzel felöntve, lefedve puhára pároljuk."]},{"section":"Zöldségek és főzés","steps":["Amikor a hús majdnem puha, hozzáadjuk a felkarikázott sárgarépát, petrezselyemgyökeret és a kockázott krumplit.","Felöntjük kb. 1.5-2 liter vízzel, és addig főzzük, amíg minden zöldség megpuhul."]},{"section":"Csipetke","steps":["A lisztből, tojásból és csipet sóból víz nélkül kemény tésztát gyúrunk.","Lisztbe mártott kézzel kis darabokat csipkedünk belőle, és a kész, gyöngyöző levesbe főzzük pár perc alatt."]}]'::jsonb),
('brassoi-aproporcolt', 'Brassói aprópecsenye', 'Szaftos sertéshús kockák ropogós fokhagymás sült burgonyával összerázva.', 'Főétel', 'Magyar', 20, 40, 4, 'könnyű', '["sertéshús","fokhagyma","krumpli","brassói"]'::jsonb, 'Images/szaftos-brassoi-apropecsenye.jpeg', '[{"group":"Hús és pác","items":[{"name":"sertésszűz vagy comb","amount":800,"unit":"g"},{"name":"kolozsvári szalonna","amount":100,"unit":"g"},{"name":"fokhagyma","amount":6,"unit":"gerezd"},{"name":"sertészsír","amount":2,"unit":"evőkanál"},{"name":"fűszerpaprika","amount":1,"unit":"teáskanál"},{"name":"só, őrölt feketebors","amount":null,"unit":"ízlés szerint"}]},{"group":"Köret","items":[{"name":"burgonya","amount":1000,"unit":"g"},{"name":"étolaj (a sütéshez)","amount":500,"unit":"ml"}]}]'::jsonb, '[{"section":"Hús elkészítése","steps":["A szalonnát kis kockákra vágjuk és a zsíron kiolvasztjuk a zsírját.","Rádobjuk a csíkokra vagy kockákra vágott sertéshúst, és magas lángon fehéredésig pirítjuk.","Sózzuk, borsozzuk, hozzáadjuk a fűszerpaprikát és a zúzott fokhagyma felét, majd fedő alatt, saját szaftjában puhára pároljuk.","A végén fedő nélkül zsírjára sütjük, és belekeverjük a maradék zúzott fokhagymát."]},{"section":"Köret és összeállítás","steps":["A krumplit megpucoljuk, apró kockákra vágjuk, és bő, forró olajban aranybarnára, ropogósra sütjük.","A kisült krumplit lecsöpögtetjük, majd még forrón összeforgatjuk a szaftos fokhagymás hússal."]}]'::jsonb),
('tejfölos-csirkepaprikas', 'Tejfölös csirkepaprikás', 'Szaftos csirkecomboly a legfinomabb tejfölös-paprikás mártásban, friss galuskával tálalva.', 'Főétel', 'Magyar', 20, 50, 4, 'közepes', '["csirke","tejföl","galuska","paprikás"]'::jsonb, 'Images/37126861_266b9316e5bf3.2e16d0ba.format-jpeg.fill-600x600.jpg', '[{"group":"Paprikás alap és hús","items":[{"name":"csirkecomb (felső vagy alsó)","amount":4,"unit":"db"},{"name":"vöröshagyma","amount":2,"unit":"db"},{"name":"zsír vagy étolaj","amount":2,"unit":"evőkanál"},{"name":"fűszerpaprika","amount":2,"unit":"evőkanál"},{"name":"TV paprika","amount":1,"unit":"db"},{"name":"paradicsom","amount":1,"unit":"db"},{"name":"só, bors","amount":null,"unit":"ízlés szerint"}]},{"group":"Mártás habarása","items":[{"name":"tejföl (20%-os)","amount":200,"unit":"g"},{"name":"finomliszt","amount":1,"unit":"evőkanál"}]}]'::jsonb, '[{"section":"Pörköltalap és szaft","steps":["A finomra vágott hagymát a zsíron üvegesre pirítjuk.","A tűzről levéve belekeverjük a pirospaprikát, hozzátesszük a felkockázott paprikát, paradicsomot és a csirkecombokat.","Sózzuk, borsozzuk, kevés vízzel felöntjük, és lefedve puha szaftosra főzzük."]},{"section":"Mártás befejezése","steps":["A megfőtt húsokat kiemeljük a szaftból.","A tejfölt elkeverjük a liszttel és kevés meleg szafttal (hőkiegyenlítés), majd a pörköltalaphoz öntjük.","Összeforraljuk a selymes mártást, majd visszatesszük bele a csirkecombokat."]}]'::jsonb),
('somloi-galuska', 'Klasszikus Somlói galuska', 'Háromféle piskóta csokiöntettel, dióbéllel, mazsolával és tejszínhabbal rétegezve.', 'Desszert', 'Magyar', 45, 25, 8, 'nehéz', '["csoki","piskóta","tejszínhab","klasszikus","sütemény"]'::jsonb, 'Images/hero-image.869568c749fcaa74.webp', '[{"group":"Piskóták (sima, kakaós, diós)","items":[{"name":"tojás","amount":6,"unit":"db"},{"name":"porcukor","amount":120,"unit":"g"},{"name":"finomliszt","amount":120,"unit":"g"},{"name":"holland kakaópor","amount":1,"unit":"evőkanál"},{"name":"darált dió","amount":2,"unit":"evőkanál"},{"name":"sütőpor","amount":0.5,"unit":"csomag"}]},{"group":"Szirup és krém","items":[{"name":"tej","amount":500,"unit":"ml"},{"name":"vaníliás pudingpor","amount":1,"unit":"csomag"},{"name":"rumaroma vagy rum","amount":2,"unit":"evőkanál"},{"name":"mazsola","amount":50,"unit":"g"},{"name":"durvára vágott dió","amount":50,"unit":"g"}]},{"group":"Csokiöntet és díszítés","items":[{"name":"étcsokoládé","amount":100,"unit":"g"},{"name":"kakaópor","amount":1,"unit":"evőkanál"},{"name":"habtejszín","amount":200,"unit":"ml"}]}]'::jsonb, '[{"section":"Piskótalapok sütése","steps":["A tojásfehérjéket habbá verjük, a sárgájákat a cukorral kikavarjuk.","A masszát 3 részre osztjuk: az egyikbe csak lisztet, a másikba kakaóport, a harmadikba darált diót keverünk.","Három külön lapot sütünk belőlük 180 °C-on kb. 10-12 perc alatt."]},{"section":"Krém és öntet","steps":["A tejből és pudingporból sűrű vaníliakrémet főzünk.","A csokoládét a kakaóporral és kevés vízzel csomómentes sűrű öntetté forraljuk."]},{"section":"Összeállítás","steps":["A lapokat egy tálba rétegezzük: diós lap, rumszirup, vaníliakrém, dió, mazsola, kakaós lap, majd a sima lap.","Hűtőbe tesszük, majd tálaláskor kanállal galuskákat szaggatunk belőle, leöntjük csokival és tejszínhabbal díszítjük."]}]'::jsonb),
('szekelykaposzta', 'Klasszikus székelykáposzta', 'Laktató egytálétel savanyú káposztából és pörkölt sertéshúsból, bőséges tejföllel dúsítva.', 'Főétel', 'Magyar', 20, 90, 6, 'közepes', '["káposzta","sertéshús","tejföl","egytálétel"]'::jsonb, 'Images/27b7b704d5044222ad872b49db7eeef3.webp', '[{"group":"Pörköltalap","items":[{"name":"sertéslapocka vagy comb","amount":800,"unit":"g"},{"name":"vöröshagyma","amount":2,"unit":"db"},{"name":"sertészsír","amount":2,"unit":"evőkanál"},{"name":"fűszerpaprika","amount":2,"unit":"evőkanál"},{"name":"fokhagyma","amount":2,"unit":"gerezd"},{"name":"só, bors, kömény","amount":null,"unit":"ízlés szerint"}]},{"group":"Káposzta és habarás","items":[{"name":"savanyú káposzta","amount":800,"unit":"g"},{"name":"tejföl (20%-os)","amount":250,"unit":"g"},{"name":"finomliszt","amount":1,"unit":"evőkanál"}]}]'::jsonb, '[{"section":"Sertéspörkölt","steps":["A hagymát zsíron üvegesre pirítjuk, majd a tűzről levéve rászórjuk a pirospaprikát.","Hozzáadjuk a kockázott sertéshúst és zúzott fokhagymát, sózzuk, fűszerezzük, majd saját levében félig puhára pároljuk."]},{"section":"Káposzta hozzákeverése","steps":["Ha a savanyú káposzta túl savanyú, hideg vízben átmossuk, majd kicsit felvágjuk.","A félig kész pörkölthöz keverjük a káposztát, felöntjük annyi vízzel, ami épp ellepi, és készre főzzük."]},{"section":"Habarás","steps":["A tejfölt elkeverjük a liszttel, behabarjuk vele az ételt, és még 5 percig összeforraljuk."]}]'::jsonb),
('turogomboc', 'Pehelykönnyű túrógombóc', 'Pehelykönnyű túrógombócok aranybarna pirított morzsában, porcukros tejföllel tálalva.', 'Desszert', 'Magyar', 15, 15, 4, 'könnyű', '["túró","zsemlemorzsa","tejföl","édes"]'::jsonb, 'Images/konnyu-puha-turogomboc.jpeg', '[{"group":"Gombóc massza","items":[{"name":"tehéntúró","amount":500,"unit":"g"},{"name":"búzadara","amount":100,"unit":"g"},{"name":"tojás (M-es)","amount":2,"unit":"db"},{"name":"kezeletlen citromhéj","amount":0.5,"unit":"db"},{"name":"só","amount":1,"unit":"csipet"}]},{"group":"Morzsa és tálalás","items":[{"name":"zsemlemorzsa","amount":150,"unit":"g"},{"name":"vaj","amount":50,"unit":"g"},{"name":"tejföl","amount":200,"unit":"g"},{"name":"porcukor","amount":2,"unit":"evőkanál"}]}]'::jsonb, '[{"section":"Massza bekeverése és pihentetés","steps":["A túrót áttörjük, összekeverjük a tojássárgájákkal, a búzadarával, citromhéjjal és a keményre vert tojáshabbal.","Hűtőben legalább 1-2 órát pihentetjük, hogy a dara megduzzadjon."]},{"section":"Morzsa és főzés","steps":["A vajat megolvasztjuk, rászórjuk a zsemlemorzsát, és szép aranybarnára pirítjuk.","A túrós alapból vizes kézzel gombócokat formázunk, majd gyöngyöző, enyhén sós vízben kifőzzük őket (miután feljöttek a víz tetejére, még 3-4 percig főzzük).","Szűrőkanállal kiemeljük, lecsöpögtetjük, és az aranybarna zsemlemorzsába forgatjuk. Porcukros tejföllel tálaljuk."]}]'::jsonb),
('rakott-krumpli', 'Hagyományos rakott krumpli', 'Rétegezett főtt burgonya, kolbász és főtt tojás rengeteg tejföllel, sütőben pirítva.', 'Főétel', 'Magyar', 30, 40, 4, 'könnyű', '["krumpli","kolbász","tojás","tejföl","rakott"]'::jsonb, 'Images/klasszikus-rakott-krumpli.jpeg', '[{"group":"Alapanyagok","items":[{"name":"burgonya","amount":1200,"unit":"g"},{"name":"tojás","amount":6,"unit":"db"},{"name":"füstölt kolbász","amount":200,"unit":"g"},{"name":"tejföl (20%-os)","amount":400,"unit":"g"},{"name":"vaj (a tepsit kikenni)","amount":20,"unit":"g"},{"name":"só, bors","amount":null,"unit":"ízlés szerint"}]}]'::jsonb, '[{"section":"Előkészítés","steps":["A burgonyát héjában, sós vízben megfőzzük. A tojásokat keményre főzzük.","Ha kihűltek, meghámozzuk és felkarikázzuk őket. A kolbászt szintén vékonyra szeleteljük."]},{"section":"Rétegezés és sütés","steps":["Egy tepsit vagy jénait kivajazunk.","Az aljára egy réteg krumplit fektetünk, sózzuk, majd eloszlatjuk rajta a tojásszeleteket, kolbászt és meglocsoljuk tejföllel.","A rétegezést addig folytatjuk, amíg a hozzávalók elfynak (a tetejére krumpli kerüljön).","A tetejét megkenjük a maradék tejföllel, és 180 °C-os sütőben kb. 35-40 perc alatt pirosra sütjük."]}]'::jsonb),
('palacsinta-alaprecept', 'Békebeli hagyományos palacsinta', 'Vékony, puha, szakadásmentes palacsintatészta, amit tetszés szerint tölthetsz lekvárral vagy túróval.', 'Desszert', 'Magyar', 10, 20, 4, 'könnyű', '["édes","palacsinta","alaprecept"]'::jsonb, 'Images/palacsinta-alaprecept.jpg', '[{"group":"Tészta","items":[{"name":"finomliszt","amount":200,"unit":"g"},{"name":"tojás","amount":2,"unit":"db"},{"name":"tej","amount":300,"unit":"ml"},{"name":"szénsavas ásványvíz","amount":200,"unit":"ml"},{"name":"étolaj","amount":2,"unit":"evőkanál"},{"name":"só","amount":1,"unit":"csipet"}]}]'::jsonb, '[{"section":"Tészta bekeverése","steps":["A lisztből, tojásokból, csipet sóból és tejszínből/tejből csomómentes sűrű tésztát keverünk.","Hozzáadjuk az ásványvizet és az olajat, majd 15-20 percet pihentetjük."]},{"section":"Sütés","steps":["Egy palacsintasütőt felforrósítunk, vékonyan megkenjük olajjal.","Egy merőkanálnyi tésztát oszlatunk el benne, majd mindkét oldalát aranysárgára sütjük."]}]'::jsonb),
('harcsapaprikas-turos-csuszaval', 'Harcsapaprikás túrós csuszával', 'Omlós harcsakockák selymes tejfölös mártásban, pirított szalonnás túrós tésztával ágyazva.', 'Főétel', 'Magyar', 25, 25, 4, 'közepes', '["hal","tészta","túró","szalonna","paprikás"]'::jsonb, 'Images/klasszikus-harcsapaprikas-hazi-turos-csuszaval.jpeg', '[{"group":"Harcsapaprikás","items":[{"name":"harcsafilé","amount":800,"unit":"g"},{"name":"vöröshagyma","amount":1,"unit":"db"},{"name":"fűszerpaprika","amount":1.5,"unit":"evőkanál"},{"name":"TV paprika","amount":1,"unit":"db"},{"name":"paradicsom","amount":1,"unit":"db"},{"name":"tejföl","amount":200,"unit":"g"},{"name":"zsír","amount":2,"unit":"evőkanál"}]},{"group":"Túrós csusza","items":[{"name":"csuszatészta","amount":400,"unit":"g"},{"name":"tehéntúró","amount":250,"unit":"g"},{"name":"tejföl","amount":150,"unit":"g"},{"name":"kolozsvári szalonna","amount":150,"unit":"g"}]}]'::jsonb, '[{"section":"Harcsapaprikás","steps":["A kockázott hagymát zsíron megpirítjuk, rászórjuk a fűszerpaprikát, a kockázott paprikát és paradicsomot.","Összefőzzük az alapját, majd hozzáadjuk a felkockázott harcsafilét és pár perc alatt óvatosan készre pároljuk.","Belekeverjük a tejfölt, összeforraljuk, majd levesszük a tűzről."]},{"section":"Túrós csusza köret","steps":["A szalonnát kockákra vágjuk és ropogósra sütjük.","A csuszatésztát sós vízben kifőzzük, leszűrjük, hozzákeverjük a túrót, tejfölt és a kisütött szalonna zsírját meg pörcét.","A túrós csuszát a szaftos harcsapaprikással tálaljuk."]}]'::jsonb),
('mezes-kremes', 'Hagyományos mézes krémes', 'Omlós mézes lapok finom grízes krémrecepttel és selymes csokoládémázzal a tetején.', 'Desszert', 'Magyar', 40, 20, 10, 'nehéz', '["méz","sütemény","csoki","ünnepi"]'::jsonb, 'Images/mezes-kremes-mezes-teszta-recept.avif', '[{"group":"Mézes lapok","items":[{"name":"finomliszt","amount":450,"unit":"g"},{"name":"termelői méz","amount":3,"unit":"evőkanál"},{"name":"porcukor","amount":150,"unit":"g"},{"name":"tojás","amount":1,"unit":"db"},{"name":"vaj","amount":50,"unit":"g"},{"name":"szódabikarbóna","amount":1,"unit":"teáskanál"}]},{"group":"Grízes krém","items":[{"name":"tej","amount":500,"unit":"ml"},{"name":"búzadara","amount":100,"unit":"g"},{"name":"vaj","amount":200,"unit":"g"},{"name":"porcukor","amount":150,"unit":"g"},{"name":"sárgabarack lekvár","amount":150,"unit":"g"}]},{"group":"Csokimáz","items":[{"name":"étcsokoládé","amount":100,"unit":"g"},{"name":"étolaj","amount":1,"unit":"evőkanál"}]}]'::jsonb, '[{"section":"Mézes lapok sütése","steps":["A mézet, vaj t, cukrot és tojást gőz felett összeforraljuk, majd a szódabikarbónás liszthez keverjük és tésztává gyúrjuk.","A tésztát 4 egyenlő részre osztjuk, vékonyra nyújtjuk, és tepsiháton 180 °C-on 6-8 perc alatt aranybarnára sütjük a lapokat."]},{"section":"Grízes krém","steps":["A tejből és búzadarából sűrű tejbegrízt főzünk, majd hagyjuk teljesen kihűlni.","A puha vajat a porcukorral habosra keverjük, majd kanalanként ledolgozzuk a kihűlt grízzel."]},{"section":"Összeállítás","steps":["Az első lapra rákenjük a krém felét, erre jön a második lap.","A második lapot megkenjük sárgabaracklekvárral, rátesszük a harmadik lapot, amire a krém másik fele kerül.","Belefedjük a negyedik lappal, leöntjük az olajjal olvasztott csokoládéval, és egy éjszakát állni hagyjuk, hogy a lapok megpuhuljanak."]}]'::jsonb);
